SHAPE_TO_FAMILY = {"HORIZONTAL_CYLINDER": "h-circ", "VERTICAL_CYLINDER": "v-cyl", "RECTANGULAR": "rect", "HORIZONTAL_ELLIPTICAL": "h-elli"}


def forwards(apps, schema_editor):
    """Anciens statuts PENDING / VALIDATED / REJECTED → nouveaux statuts ; cotes m → cm (familles du calculateur)."""
    Tank = apps.get_model("fuel_tracking", "FuelTankMaster")
    for t in Tank.objects.all():
        fam = SHAPE_TO_FAMILY.get(t.shape)
        cm = lambda v: None if v is None else v * 100  # noqa: E731
        if fam and t.dimension_1_cm is None:
            t.shape_family = fam
            t.bottom_profile = t.bottom_profile or "plat"
            t.top_profile = t.top_profile or "plat"
            if fam == "h-circ":
                t.dimension_1_cm, t.dimension_3_cm = cm(t.diameter_m), cm(t.length_m)
            elif fam == "v-cyl":
                t.dimension_1_cm, t.dimension_2_cm = cm(t.diameter_m), cm(t.height_m)
            else:  # rect / h-elli : largeur, hauteur, longueur
                t.dimension_1_cm, t.dimension_2_cm, t.dimension_3_cm = cm(t.width_m), cm(t.height_m), cm(t.length_m)
        old = t.validation_status
        if old == "VALIDATED":
            t.validation_status = "VALIDEE"
        elif old == "REJECTED":
            t.validation_status = "REJETEE"
        elif old == "PENDING":
            dims = {"h-circ": (t.dimension_1_cm, t.dimension_3_cm), "v-cyl": (t.dimension_1_cm, t.dimension_2_cm)}.get(
                fam, (t.dimension_1_cm, t.dimension_2_cm, t.dimension_3_cm))
            if fam and all(dims):
                t.validation_status = "PROPOSEE"
            elif t.capacity_l:
                t.validation_status = "A_CONFIRMER"
            else:
                t.validation_status = "INCOMPLETE"
            t.validation_reason = "Statut repris de l'ancien référentiel (À valider) — à réévaluer : python manage.py evaluate_site_tanks"
        t.save()


def backwards(apps, schema_editor):
    Tank = apps.get_model("fuel_tracking", "FuelTankMaster")
    Tank.objects.filter(validation_status="VALIDEE").update(validation_status="VALIDATED")
    Tank.objects.filter(validation_status="REJETEE").update(validation_status="REJECTED")
    Tank.objects.exclude(validation_status__in=["VALIDATED", "REJECTED"]).update(validation_status="PENDING")


